    // Mixed case
    console.log(longestSubstring("aAb") === 3); // "aAb" (case-sensitive)

    // Spaces and punctuation
    console.log(longestSubstring("a b c") === 3); // "a b" or "b c"
    console.log(longestSubstring("a!b@c#d$") === 5); // "b@c#d"

