    // Unicode cases
    console.log(longestSubstring("👨‍👩‍👧‍👦👨‍👩‍👧‍👦") === 1); // Family emoji with skin tones (same emoji repeated)
    console.log(longestSubstring("café") === 4); // é is a single code point
    console.log(longestSubstring("naïve") === 5); // ï is a single code point

    // Combining marks
    console.log(longestSubstring("e\u0301\u0302") === 2); // "e" + combining acute + combining circumflex
    console.log(longestSubstring("a\u0301b\u0302c\u0303") === 3); // Each base char with one combining mark

    // Surrogate pairs (emoji)
    console.log(longestSubstring("👨‍👩‍👧‍👦a") === 2); // Family emoji + "a"
    console.log(longestSubstring("👨‍👩‍👧‍👦👩") === 2); // Family emoji + woman emoji

    // Mixed combining marks and base characters
    console.log(longestSubstring("a\u0301b\u0302c\u0303d") === 4);

    // All unique characters
    console.log(longestSubstring("abcdefghijklmnopqrstuvwxyz") === 26);

